// Knowledge index: loads pre-built chunks from config.knowledgePath and serves
// BM25 search over them. Zero dependencies, everything in memory.
//
// File shape (generated by knowledge/build-knowledge.mjs):
//   { builtAt, chunks: [{ id, project, source, title, text }] }
// A missing, unreadable or malformed file yields an empty index (never throws).

import { readFile } from 'node:fs/promises';

const K1 = 1.5;
const B = 0.75;
// A term in the title counts as this many occurrences in the body.
const TITLE_BOOST = 3;
const GENERAL = 'general';

// Tashkeel (U+064B–U+0652), superscript alef (U+0670) and tatweel (U+0640).
const AR_STRIP = /[ً-ْٰـ]/g;
const AR_ALEF = /[أإآٱ]/g; // أ إ آ ٱ → ا
const AR_YA = /ى/g; // ى → ي
const AR_TA_MARBUTA = /ة/g; // ة → ه
const NON_WORD = /[^\p{L}\p{N}]+/u;

function normalize(text) {
  return String(text)
    .normalize('NFKC')
    .toLowerCase()
    .replace(AR_STRIP, '')
    .replace(AR_ALEF, 'ا')
    .replace(AR_YA, 'ي')
    .replace(AR_TA_MARBUTA, 'ه');
}

const STOP_WORDS_RAW = [
  // English
  'the', 'an', 'and', 'or', 'of', 'to', 'in', 'on', 'for', 'is', 'are', 'was', 'were', 'be',
  'been', 'it', 'its', 'this', 'that', 'these', 'those', 'with', 'as', 'at', 'by', 'from',
  'not', 'but', 'if', 'so', 'do', 'does', 'did', 'can', 'will', 'has', 'have', 'had',
  'what', 'which', 'who', 'how', 'when', 'where', 'why', 'me', 'my', 'we', 'our', 'you',
  'your', 'he', 'she', 'they', 'them', 'their', 'there', 'about', 'into', 'than', 'then',
  // Arabic
  'في', 'من', 'على', 'إلى', 'عن', 'مع', 'هذا', 'هذه', 'ذلك', 'تلك', 'التي', 'الذي', 'الذين',
  'ما', 'ماذا', 'هل', 'أن', 'إن', 'كان', 'كانت', 'يكون', 'هو', 'هي', 'هم', 'نحن', 'أنا', 'أنت',
  'أو', 'ثم', 'قد', 'لا', 'لم', 'لن', 'كل', 'بين', 'حتى', 'كما', 'لكن', 'بعد', 'قبل', 'عند',
  'هناك', 'هنا', 'كيف', 'متى', 'أين', 'لماذا', 'أي', 'يا', 'ايضا', 'أيضاً', 'غير', 'إذا',
];
const STOP_WORDS = new Set(STOP_WORDS_RAW.map(normalize));

/**
 * Tokenise text for indexing and querying.
 * Lowercases, applies Arabic normalisation, splits on anything that is not a
 * Unicode letter or digit, drops one-character tokens and stop words.
 * @param {string} text
 * @returns {string[]}
 */
export function tokenize(text) {
  if (text === null || text === undefined) return [];
  const parts = normalize(text).split(NON_WORD);
  const out = [];
  for (const p of parts) {
    if (p.length < 2 || STOP_WORDS.has(p)) continue;
    out.push(p);
  }
  return out;
}

async function loadFile(path) {
  if (!path) return { builtAt: null, chunks: [] };
  try {
    const data = JSON.parse(await readFile(path, 'utf8'));
    if (!data || typeof data !== 'object' || !Array.isArray(data.chunks)) {
      return { builtAt: null, chunks: [] };
    }
    return { builtAt: data.builtAt ?? null, chunks: data.chunks };
  } catch {
    return { builtAt: null, chunks: [] };
  }
}

function str(v, fallback = '') {
  return typeof v === 'string' ? v : fallback;
}

function buildIndex(rawChunks) {
  const docs = [];
  const projects = {};
  // term -> { ids: number[], tfs: number[] } (ids ascending by construction)
  const postings = new Map();
  const lengths = [];
  let totalLength = 0;

  for (const raw of rawChunks) {
    if (!raw || typeof raw !== 'object') continue;
    const text = str(raw.text);
    const title = str(raw.title);
    if (!text.trim() && !title.trim()) continue;
    const doc = {
      project: str(raw.project).trim() || GENERAL,
      source: str(raw.source),
      title,
      text,
    };

    const tf = new Map();
    const bodyTokens = tokenize(text);
    for (const t of bodyTokens) tf.set(t, (tf.get(t) || 0) + 1);
    const titleTokens = tokenize(title);
    for (const t of titleTokens) tf.set(t, (tf.get(t) || 0) + TITLE_BOOST);

    const id = docs.length;
    docs.push(doc);
    projects[doc.project] = (projects[doc.project] || 0) + 1;
    const len = bodyTokens.length + titleTokens.length * TITLE_BOOST;
    lengths.push(len);
    totalLength += len;

    for (const [term, count] of tf) {
      let p = postings.get(term);
      if (!p) {
        p = { ids: [], tfs: [] };
        postings.set(term, p);
      }
      p.ids.push(id);
      p.tfs.push(count);
    }
  }

  const n = docs.length;
  const avgLength = n ? totalLength / n : 0;
  // Per-document length normalisation factor, precomputed once.
  const norm = new Float64Array(n);
  for (let i = 0; i < n; i++) {
    norm[i] = K1 * (1 - B + (avgLength ? (B * lengths[i]) / avgLength : 0));
  }
  // Freeze postings into typed arrays and precompute idf.
  for (const [term, p] of postings) {
    const df = p.ids.length;
    postings.set(term, {
      ids: Int32Array.from(p.ids),
      tfs: Float32Array.from(p.tfs),
      idf: Math.log(1 + (n - df + 0.5) / (df + 0.5)),
    });
  }
  return { docs, projects, postings, norm };
}

/**
 * @param {{ config: { knowledgePath: string } }} options
 */
export async function createKnowledge({ config } = {}) {
  const { builtAt, chunks } = await loadFile(config && config.knowledgePath);
  const { docs, projects, postings, norm } = buildIndex(chunks);
  const scores = new Float64Array(docs.length);

  function search(query, { project, k = 5 } = {}) {
    const limit = Number.isFinite(k) ? Math.floor(k) : 5;
    if (limit <= 0 || docs.length === 0 || typeof query !== 'string') return [];
    const terms = new Set(tokenize(query));
    if (terms.size === 0) return [];

    // No project (or the admin wildcard) searches everything.
    const filter = typeof project === 'string' && project && project !== '*' ? project : null;
    const touched = [];
    for (const term of terms) {
      const p = postings.get(term);
      if (!p) continue;
      const { ids, tfs, idf } = p;
      for (let i = 0; i < ids.length; i++) {
        const id = ids[i];
        if (filter) {
          const dp = docs[id].project;
          if (dp !== filter && dp !== GENERAL) continue;
        }
        const tf = tfs[i];
        if (scores[id] === 0) touched.push(id);
        scores[id] += (idf * tf * (K1 + 1)) / (tf + norm[id]);
      }
    }

    touched.sort((a, b) => scores[b] - scores[a] || a - b);
    const out = [];
    for (let i = 0; i < touched.length; i++) {
      const id = touched[i];
      if (out.length < limit && scores[id] > 0) {
        const d = docs[id];
        out.push({
          project: d.project,
          source: d.source,
          title: d.title,
          text: d.text,
          score: scores[id],
        });
      }
      scores[id] = 0; // reset the shared accumulator for the next query
    }
    return out;
  }

  function stats() {
    return { chunks: docs.length, builtAt, projects: { ...projects } };
  }

  return { search, stats };
}
